css.value:
* {
    color: rgb(var(--now-color_text--tertiary));
    margin: 0;
    font-style: normal;
    font-weight: normal;
    line-height: normal;
}

* {
    color: rgb(var(--now-color_text--primary));
    font-family: var(--now-font-family);
    font-style: normal;
    font-weight: var(--now-card-header_heading--title--font-weight);
    line-height: normal;
    margin:0;
}

* {
    color: rgb(var(--now-color_text--primary));
    font-size: 16px;
    font-style: normal;
    font-weight: var(--now-card-header_heading--title--font-weight);
    line-height: normal;
}

* {
    color: rgb(var(--now-color_text--primary));
    font-size: 16px;
    font-style: normal;
    font-weight: var(--now-card-header_heading--title--font-weight);
    line-height: normal;
}

* {
    color: rgb(var(--now-color_text--tertiary));
    font-size: 12px;
    font-style: normal;
    font-weight: 400;
    line-height: normal;
}

* {
    color: rgb(var(--now-color_text--primary));
    font-family: 'Lato';
    margin:0;
    font-style: normal;
    font-weight: 400;
    line-height: normal;
}

* {
    font-family: 'Lato';
    font-feature-settings: 'liga' off, 'clig' off;
    font-size: 16px;
    font-weight: 400;
    line-height: 20px;
    text-align: left;
    padding: var(--now-scalable-space--sm);
}
